package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.util.*;
public class GrantReadinessActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);render();}
 @Override protected void onResume(){super.onResume();if(!isFinishing())render();}
 private void render(){LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"État du dossier",27,true));r.addView(Ui.text(this,"Contrôle interne des éléments techniques, documentaires et des pièces justificatives avant dépôt.",13,false));List<String> ready=new ArrayList<>(),incomplete=new ArrayList<>(),blockers=new ArrayList<>();evaluate(ready,incomplete,blockers);int pieces=SupportingDocumentsActivity.completedCount(this);if(pieces<10)incomplete.add("Pièces justificatives : "+pieces+" / 10 disponibles.");else ready.add("Pièces justificatives complètes : 10 / 10.");boolean internalReady=blockers.isEmpty()&&incomplete.isEmpty();LinearLayout summary=Ui.panel(this);summary.addView(Ui.text(this,internalReady?"PRÊT À DÉPOSER DANS L’OUTIL":"DOSSIER À COMPLÉTER",22,true));int total=ready.size()+incomplete.size()+blockers.size();int score=total==0?0:(int)Math.round(ready.size()*100.0/total);summary.addView(Ui.text(this,"Préparation documentaire : "+score+" %\nPrêts : "+ready.size()+" · Incomplets : "+incomplete.size()+" · Bloquants : "+blockers.size(),16,true));summary.addView(Ui.text(this,internalReady?"Tous les contrôles internes configurés sont satisfaits. Vérifiez encore les règles et formulaires officiels avant l’envoi.":blockers.isEmpty()?"Aucun blocage critique, mais le dossier n’est pas encore complet.":"Corrigez d’abord les éléments bloquants.",13,false));r.addView(summary);addActions(r,internalReady,pieces);addGroup(r,"BLOQUANTS",blockers,"Aucun blocage détecté.");addGroup(r,"INCOMPLETS",incomplete,"Aucun élément incomplet.");addGroup(r,"PRÊTS",ready,"Aucun élément marqué prêt.");LinearLayout finalBox=Ui.panel(this);finalBox.addView(Ui.text(this,"Résumé final avant dépôt",20,true));finalBox.addView(Ui.text(this,finalSummary(ready,incomplete,blockers,internalReady),14,false));Button share=Ui.primary(this,"Partager le résumé final");share.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,"Culture du Québec — état final du dossier");i.putExtra(Intent.EXTRA_TEXT,finalSummary(ready,incomplete,blockers,internalReady));startActivity(Intent.createChooser(i,"Partager"));});finalBox.addView(share);r.addView(finalBox);r.addView(Ui.text(this,"Le statut prêt à déposer est un contrôle interne seulement. Il ne constitue pas une certification ni une décision d’admissibilité.",12,false));setContentView(Ui.wrap(this,r));}
 private void addActions(LinearLayout root,boolean internalReady,int pieces){LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,internalReady?"Dernière vérification":"Corrections rapides",20,true));SharedPreferences plan=getSharedPreferences("standardisation_plan",0);if(plan.getString("org","").trim().isEmpty()||plan.getString("resp","").trim().isEmpty()||missingPlan(plan)){Button b=Ui.primary(this,"Compléter le plan de gestion");b.setOnClickListener(v->startActivity(new Intent(this,StandardizationCenterActivity.class)));p.addView(b);}List<DocumentStore.Item> docs=DocumentStore.list(this);if(docs.isEmpty()){Button b=Ui.primary(this,"Importer un catalogue");b.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));p.addView(b);}else{DocumentStore.Item d=docs.get(0);boolean mapped=false,validated=false;try{for(DataNormalizer.ColumnMapping m:DocumentStore.readMappings(this,d)){if(m.targetField!=null&&!m.targetField.isBlank())mapped=true;if(m.humanValidated)validated=true;}}catch(Exception ignored){}if(!mapped||!validated){Button b=Ui.primary(this,"Cartographier et valider les champs");b.setOnClickListener(v->{Intent i=new Intent(this,MappingActivity.class);i.putExtra("id",d.id);startActivity(i);});p.addView(b);}}SharedPreferences budget=getSharedPreferences("budget",0);if(budget.getFloat("total",0f)<=0||budgetProblem(budget)){Button b=Ui.primary(this,"Corriger le budget");b.setOnClickListener(v->startActivity(new Intent(this,BudgetActivity.class)));p.addView(b);}SharedPreferences team=getSharedPreferences("team_capacity",0);if(team.getString("chef","").trim().isEmpty()||team.getString("competences","").trim().isEmpty()){Button b=Ui.secondary(this,"Compléter l’équipe et les compétences");b.setOnClickListener(v->startActivity(new Intent(this,TeamCapacityActivity.class)));p.addView(b);}SharedPreferences timeline=getSharedPreferences("timeline",0);int planned=0;for(int i=0;i<7;i++)if(!timeline.getString("months"+i,"").trim().isEmpty())planned++;if(planned<7){Button b=Ui.secondary(this,"Compléter l’échéancier");b.setOnClickListener(v->startActivity(new Intent(this,ProjectTimelineActivity.class)));p.addView(b);}SharedPreferences checklist=getSharedPreferences("application_checklist",0);int checked=0;for(int i=0;i<14;i++)if(checklist.getBoolean("i"+i,false))checked++;if(checked<14){Button b=Ui.secondary(this,"Compléter la checklist");b.setOnClickListener(v->startActivity(new Intent(this,ApplicationChecklistActivity.class)));p.addView(b);}if(pieces<10){Button b=Ui.primary(this,"Compléter les pièces justificatives");b.setOnClickListener(v->startActivity(new Intent(this,SupportingDocumentsActivity.class)));p.addView(b);}if(internalReady){Button dossier=Ui.primary(this,"Ouvrir le dossier consolidé");dossier.setOnClickListener(v->startActivity(new Intent(this,GrantPackageActivity.class)));p.addView(dossier);}Button refresh=Ui.secondary(this,"Recalculer l’état du dossier");refresh.setOnClickListener(v->render());p.addView(refresh);root.addView(p);}
 private boolean missingPlan(SharedPreferences p){for(String k:new String[]{"sources","quality","sharing","backup","target","schedule"})if(p.getString(k,"").trim().isEmpty())return true;return false;}
 private boolean budgetProblem(SharedPreferences b){double t=b.getFloat("total",0f);return t<=0||num(b.getString("training","0"))>t*.20||num(b.getString("admin","0"))>t*.05||num(b.getString("contingency","0"))>t*.10;}
 private void evaluate(List<String> ready,List<String> incomplete,List<String> blockers){SharedPreferences plan=getSharedPreferences("standardisation_plan",0);String org=plan.getString("org","").trim(),resp=plan.getString("resp","").trim();if(org.isEmpty())blockers.add("Organisation non renseignée.");else ready.add("Organisation renseignée.");if(resp.isEmpty())incomplete.add("Responsable des données à renseigner.");else ready.add("Responsable des données identifié.");String[] ks={"sources","quality","sharing","backup","target","schedule"};String[] ls={"Sources et provenance","Contrôle qualité","Partage / données ouvertes","Sauvegardes et conservation","Cible mesurable","Échéancier global"};for(int i=0;i<ks.length;i++){if(plan.getString(ks[i],"").trim().isEmpty())incomplete.add(ls[i]+" à compléter.");else ready.add(ls[i]+" documenté.");}List<DocumentStore.Item> docs=DocumentStore.list(this);if(docs.isEmpty())blockers.add("Aucun catalogue importé.");else ready.add(docs.size()+" catalogue(s) importé(s).");int mappings=0,validated=0,unmapped=0;for(DocumentStore.Item d:docs)try{for(DataNormalizer.ColumnMapping m:DocumentStore.readMappings(this,d)){if(m.targetField!=null&&!m.targetField.isBlank())mappings++;else unmapped++;if(m.humanValidated)validated++;}}catch(Exception e){incomplete.add("Audit de cartographie illisible pour "+d.name+".");}if(!docs.isEmpty()&&mappings==0)blockers.add("Aucune correspondance de champs enregistrée.");else if(mappings>0)ready.add(mappings+" correspondance(s) de champs enregistrée(s).");if(mappings>0&&validated==0)blockers.add("Aucune correspondance validée humainement.");else if(validated>0)ready.add(validated+" correspondance(s) validée(s) humainement.");if(unmapped>0)incomplete.add(unmapped+" colonne(s) restent sans cible.");SharedPreferences budget=getSharedPreferences("budget",0);float total=budget.getFloat("total",0f);if(total<=0)blockers.add("Budget non préparé ou total égal à 0 $.");else{ready.add("Budget préparé : "+String.format(java.util.Locale.CANADA_FRENCH,"%.2f $",total));if(budgetProblem(budget))blockers.add("Le budget dépasse au moins un plafond interne contrôlé.");}SharedPreferences team=getSharedPreferences("team_capacity",0);if(team.getString("chef","").trim().isEmpty())incomplete.add("Responsable du projet non identifié.");else ready.add("Responsable du projet identifié.");if(team.getString("competences","").trim().isEmpty())incomplete.add("Compétences de l’équipe à documenter.");else ready.add("Capacité de l’équipe documentée.");SharedPreferences timeline=getSharedPreferences("timeline",0);int planned=0;for(int i=0;i<7;i++)if(!timeline.getString("months"+i,"").trim().isEmpty())planned++;if(planned==0)blockers.add("Échéancier du projet non préparé.");else if(planned<7)incomplete.add("Échéancier partiel : "+planned+" / 7 phases.");else ready.add("Les 7 phases sont planifiées.");SharedPreferences checklist=getSharedPreferences("application_checklist",0);int checked=0;for(int i=0;i<14;i++)if(checklist.getBoolean("i"+i,false))checked++;if(checked<7)blockers.add("Checklist trop incomplète : "+checked+" / 14.");else if(checked<14)incomplete.add("Checklist : "+checked+" / 14.");else ready.add("Checklist complète : 14 / 14.");}
 private void addGroup(LinearLayout root,String title,List<String> items,String empty){LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,title,20,true));if(items.isEmpty())p.addView(Ui.text(this,empty,14,false));else for(String x:items)p.addView(Ui.text(this,"• "+x,14,false));root.addView(p);}
 private String finalSummary(List<String> ready,List<String> incomplete,List<String> blockers,boolean internalReady){StringBuilder s=new StringBuilder("CULTURE DU QUÉBEC — CONTRÔLE FINAL\n\nSTATUT INTERNE : ").append(internalReady?"PRÊT À DÉPOSER DANS L’OUTIL":"À COMPLÉTER").append("\n\n");if(!blockers.isEmpty()){s.append("BLOQUANTS\n");for(String x:blockers)s.append("- ").append(x).append('\n');s.append('\n');}if(!incomplete.isEmpty()){s.append("INCOMPLETS\n");for(String x:incomplete)s.append("- ").append(x).append('\n');s.append('\n');}s.append("ÉLÉMENTS VALIDÉS\n");for(String x:ready)s.append("- ").append(x).append('\n');s.append("\nContrôle interne uniquement. Vérifier les règles officielles avant l’envoi.");return s.toString();}
 private double num(String v){try{return Double.parseDouble(v.replace(',','.'));}catch(Exception e){return 0;}}
}
